    INSERT INTO Messages (Code, Texts)
    VALUES
        ('UNEXPECTED_ERROR', N'{"en":"Something went wrong. Please try again.","hi":"कुछ गलत हो गया। कृपया फिर से प्रयास करें।","ar":"حدث خطأ ما. يرجى المحاولة مرة أخرى."}'),
        ('SPEEDTEST_SIZE_INVALID', N'{"en":"The requested size must be between 0 and {0} bytes.","hi":"अनुरोधित आकार 0 से {0} बाइट के बीच होना चाहिए।","ar":"يجب أن يكون الحجم المطلوب بين 0 و {0} بايت."}'),
        ('AUTH_SIGNED_UP', N'{"en":"Your account was created.","hi":"आपका खाता बन गया।","ar":"تم إنشاء حسابك."}'),
        ('AUTH_LOGIN_INVALID', N'{"en":"The e-mail or password is not correct.","hi":"ई-मेल या पासवर्ड सही नहीं है।","ar":"البريد الإلكتروني أو كلمة المرور غير صحيحة."}'),
        ('AUTH_LOCKED', N'{"en":"Too many wrong tries. Try again in {0} minutes.","hi":"बहुत सारी गलत कोशिशें। {0} मिनट बाद फिर कोशिश करें।","ar":"محاولات خاطئة كثيرة. حاول مرة أخرى بعد {0} دقيقة."}'),
        ('AUTH_EMAIL_INVALID', N'{"en":"Enter a valid e-mail address.","hi":"मान्य ई-मेल पता दर्ज करें।","ar":"أدخل عنوان بريد إلكتروني صالحًا."}'),
        ('AUTH_EMAIL_TAKEN', N'{"en":"An account with this e-mail already exists. Log in instead.","hi":"इस ई-मेल से पहले से एक खाता है। इसके बजाय लॉग इन करें।","ar":"يوجد حساب بهذا البريد الإلكتروني بالفعل. سجّل الدخول بدلًا من ذلك."}'),
        ('AUTH_PASSWORD_WEAK', N'{"en":"The password must be at least {0} characters long.","hi":"पासवर्ड कम से कम {0} अक्षरों का होना चाहिए।","ar":"يجب ألا تقل كلمة المرور عن {0} أحرف."}'),
        ('AUTH_PASSWORD_WRONG', N'{"en":"The current password is not correct.","hi":"मौजूदा पासवर्ड सही नहीं है।","ar":"كلمة المرور الحالية غير صحيحة."}'),
        ('AUTH_PASSWORD_CHANGED', N'{"en":"Your password was changed. Other devices have been logged out.","hi":"आपका पासवर्ड बदल दिया गया। दूसरे डिवाइस से लॉग आउट कर दिया गया है।","ar":"تم تغيير كلمة المرور. تم تسجيل الخروج من الأجهزة الأخرى."}'),
        ('AUTH_PROFILE_SAVED', N'{"en":"Your profile was saved.","hi":"आपकी प्रोफ़ाइल सहेज ली गई।","ar":"تم حفظ ملفك الشخصي."}'),
        ('AUTH_PROFILE_INVALID', N'{"en":"Enter a name of up to {0} characters and choose a language.","hi":"{0} अक्षरों तक का नाम दर्ज करें और भाषा चुनें।","ar":"أدخل اسمًا لا يزيد عن {0} حرفًا واختر لغة."}'),
        ('AUTH_SESSION_INVALID', N'{"en":"Your session has ended. Please log in again.","hi":"आपका सत्र समाप्त हो गया। कृपया फिर से लॉग इन करें।","ar":"انتهت جلستك. يرجى تسجيل الدخول مرة أخرى."}'),
        ('AUTH_LOGGED_OUT', N'{"en":"You have been logged out.","hi":"आप लॉग आउट हो गए हैं।","ar":"تم تسجيل خروجك."}'),
        ('AUTH_FORBIDDEN', N'{"en":"You do not have access to this. Ask an administrator to give you access.","hi":"आपके पास इसकी पहुँच नहीं है। किसी एडमिन से पहुँच देने के लिए कहें।","ar":"ليس لديك صلاحية الوصول إلى هذا. اطلب من المسؤول منحك الصلاحية."}'),
        ('AUTH_USER_NOT_FOUND', N'{"en":"This user was not found.","hi":"यह उपयोगकर्ता नहीं मिला।","ar":"لم يتم العثور على هذا المستخدم."}'),
        ('AUTH_APP_UNKNOWN', N'{"en":"The app \"{0}\" does not exist.","hi":"ऐप \"{0}\" मौजूद नहीं है।","ar":"التطبيق \"{0}\" غير موجود."}'),
        ('AUTH_LAST_ADMIN', N'{"en":"At least one super admin must remain.","hi":"कम से कम एक सुपर एडमिन रहना चाहिए।","ar":"يجب أن يبقى مسؤول أعلى واحد على الأقل."}'),
        ('AUTH_ACCESS_SAVED', N'{"en":"Access was saved.","hi":"पहुँच सहेज ली गई।","ar":"تم حفظ الصلاحيات."}'),
        ('AUTH_USER_CREATED', N'{"en":"The user was added.","hi":"उपयोगकर्ता जोड़ दिया गया।","ar":"تمت إضافة المستخدم."}'),
        ('AUTH_AVATAR_SAVED', N'{"en":"Your picture was saved.","hi":"आपकी तस्वीर सहेज ली गई।","ar":"تم حفظ صورتك."}'),
        ('AUTH_AVATAR_REMOVED', N'{"en":"Your picture was removed.","hi":"आपकी तस्वीर हटा दी गई।","ar":"تمت إزالة صورتك."}'),
        ('AUTH_AVATAR_INVALID', N'{"en":"Choose a JPG, PNG or WebP picture of up to {0} MB.","hi":"{0} MB तक की JPG, PNG या WebP तस्वीर चुनें।","ar":"اختر صورة JPG أو PNG أو WebP بحجم {0} ميغابايت كحد أقصى."}'),
        ('AUTH_AVATAR_NOT_FOUND', N'{"en":"This user has no picture.","hi":"इस उपयोगकर्ता की कोई तस्वीर नहीं है।","ar":"لا توجد صورة لهذا المستخدم."}'),
        ('AUTH_USER_DELETED', N'{"en":"The user was deleted and logged out everywhere.","hi":"उपयोगकर्ता हटा दिया गया और हर जगह से लॉग आउट कर दिया गया।","ar":"تم حذف المستخدم وتسجيل خروجه من كل الأجهزة."}'),
        ('AUTH_USER_ARCHIVED', N'{"en":"The user was archived and logged out everywhere. They cannot log in until activated again.","hi":"उपयोगकर्ता को संग्रहित कर दिया गया और हर जगह से लॉग आउट कर दिया गया। दोबारा सक्रिय होने तक वे लॉग इन नहीं कर सकते।","ar":"تمت أرشفة المستخدم وتسجيل خروجه من كل الأجهزة. لا يمكنه تسجيل الدخول حتى يُعاد تفعيله."}'),
        ('AUTH_USER_ACTIVATED', N'{"en":"The user was activated and can log in again.","hi":"उपयोगकर्ता को सक्रिय कर दिया गया और वे फिर से लॉग इन कर सकते हैं।","ar":"تم تفعيل المستخدم ويمكنه تسجيل الدخول مرة أخرى."}'),
        ('AUTH_USER_RESTORED', N'{"en":"The user was restored. They can log in again unless they are archived.","hi":"उपयोगकर्ता को वापस लाया गया। संग्रहित न होने पर वे फिर से लॉग इन कर सकते हैं।","ar":"تمت استعادة المستخدم. يمكنه تسجيل الدخول مرة أخرى ما لم يكن مؤرشفًا."}'),
        ('AUTH_ACCOUNT_DELETED', N'{"en":"Your account was deleted and you were logged out everywhere.","hi":"आपका खाता हटा दिया गया और आपको हर जगह से लॉग आउट कर दिया गया।","ar":"تم حذف حسابك وتسجيل خروجك من كل الأجهزة."}'),
        ('AUTH_ACCOUNT_ARCHIVED', N'{"en":"Your account is archived. Ask an administrator to activate it again.","hi":"आपका खाता संग्रहित है। इसे फिर से सक्रिय करने के लिए किसी एडमिन से कहें।","ar":"حسابك مؤرشف. اطلب من أحد المسؤولين إعادة تفعيله."}'),
        ('AUTH_ACCOUNT_CLOSED', N'{"en":"This account was deleted and can no longer log in.","hi":"यह खाता हटा दिया गया है और अब लॉग इन नहीं कर सकता।","ar":"تم حذف هذا الحساب ولم يعد بإمكانه تسجيل الدخول."}'),
        ('AUTH_OWN_ACCOUNT', N'{"en":"You cannot change your own role or delete your own account.","hi":"आप अपनी भूमिका नहीं बदल सकते और अपना खाता नहीं हटा सकते।","ar":"لا يمكنك تغيير دورك أو حذف حسابك."}'),
        ('AUTH_FEATURES_SAVED', N'{"en":"Your page options were saved.","hi":"आपके पेज विकल्प सहेज लिए गए।","ar":"تم حفظ خيارات صفحاتك."}'),
        ('AUTH_FEATURE_UNKNOWN', N'{"en":"The option \"{0}\" cannot be changed here.","hi":"विकल्प \"{0}\" यहाँ नहीं बदला जा सकता।","ar":"لا يمكن تغيير الخيار \"{0}\" هنا."}'),
        ('ROLE_NOT_FOUND', N'{"en":"This role was not found.","hi":"यह भूमिका नहीं मिली।","ar":"لم يتم العثور على هذا الدور."}'),
        ('ROLE_INVALID', N'{"en":"Enter a code of 2 to {0} small letters, digits or dashes (starting with a letter), a name of up to {1} characters and a description of up to {2} characters.","hi":"2 से {0} छोटे अक्षरों, अंकों या डैश का कोड (अक्षर से शुरू), {1} अक्षरों तक का नाम और {2} अक्षरों तक का विवरण दर्ज करें।","ar":"أدخل رمزًا من 2 إلى {0} من الأحرف الصغيرة أو الأرقام أو الشرطات (يبدأ بحرف)، واسمًا لا يزيد عن {1} حرفًا، ووصفًا لا يزيد عن {2} حرفًا."}'),
        ('ROLE_CODE_TAKEN', N'{"en":"A role with the code \"{0}\" already exists.","hi":"\"{0}\" कोड वाली भूमिका पहले से मौजूद है।","ar":"يوجد دور بالرمز \"{0}\" بالفعل."}'),
        ('ROLE_SYSTEM_LOCKED', N'{"en":"Built-in roles cannot be deleted and their code cannot change.","hi":"बिल्ट-इन भूमिकाएँ हटाई नहीं जा सकतीं और उनका कोड नहीं बदल सकता।","ar":"لا يمكن حذف الأدوار المدمجة ولا تغيير رمزها."}'),
        ('ROLE_IN_USE', N'{"en":"This role is given to {0} user(s). Give them another role first.","hi":"यह भूमिका {0} उपयोगकर्ताओं को दी गई है। पहले उन्हें दूसरी भूमिका दें।","ar":"هذا الدور ممنوح لـ {0} مستخدم. امنحهم دورًا آخر أولًا."}'),
        ('ROLE_SUPER_ADMIN_ONLY', N'{"en":"Only a super admin can change super admins, the super admin role or its rights.","hi":"केवल सुपर एडमिन ही सुपर एडमिन, सुपर एडमिन भूमिका या उसके अधिकार बदल सकता है।","ar":"لا يمكن إلا للمسؤول الأعلى تغيير المسؤولين الأعلى أو دورهم أو صلاحياته."}'),
        ('ROLE_DEFAULT_REQUIRED', N'{"en":"One role must stay the sign-up role. Make another role the sign-up role first.","hi":"एक भूमिका को साइन-अप भूमिका रहना चाहिए। पहले किसी दूसरी भूमिका को साइन-अप भूमिका बनाएं।","ar":"يجب أن يبقى دور واحد دور التسجيل. اجعل دورًا آخر دور التسجيل أولًا."}'),
        ('ROLE_DEFAULT_INVALID', N'{"en":"The super admin role cannot be the sign-up role.","hi":"सुपर एडमिन भूमिका साइन-अप भूमिका नहीं हो सकती।","ar":"لا يمكن أن يكون دور المسؤول الأعلى دور التسجيل."}'),
        ('ROLE_SAVED', N'{"en":"The role was saved.","hi":"भूमिका सहेज ली गई।","ar":"تم حفظ الدور."}'),
        ('ROLE_DELETED', N'{"en":"The role was deleted.","hi":"भूमिका हटा दी गई।","ar":"تم حذف الدور."}'),
        ('PERMISSION_NOT_FOUND', N'{"en":"These rights were not found.","hi":"ये अधिकार नहीं मिले।","ar":"لم يتم العثور على هذه الصلاحيات."}'),
        ('PERMISSION_PAGE_UNKNOWN', N'{"en":"This page does not exist.","hi":"यह पेज मौजूद नहीं है।","ar":"هذه الصفحة غير موجودة."}'),
        ('PERMISSION_EXISTS', N'{"en":"This role already has rights on this page. Change them in its row.","hi":"इस भूमिका के पास इस पेज पर पहले से अधिकार हैं। उन्हें उसकी पंक्ति में बदलें।","ar":"لهذا الدور صلاحيات على هذه الصفحة بالفعل. غيّرها في صفها."}'),
        ('PERMISSION_SAVED', N'{"en":"The rights were saved.","hi":"अधिकार सहेज लिए गए।","ar":"تم حفظ الصلاحيات."}'),
        ('PERMISSION_DELETED', N'{"en":"The page was taken away from the role.","hi":"पेज भूमिका से हटा दिया गया।","ar":"تمت إزالة الصفحة من الدور."}'),
        ('MUSIC_PLAYER_NOT_FOUND', N'{"en":"This player was not found.","hi":"यह प्लेयर नहीं मिला।","ar":"لم يتم العثور على هذا المشغل."}'),
        ('MUSIC_TRACK_NOT_FOUND', N'{"en":"This track was not found.","hi":"यह ट्रैक नहीं मिला।","ar":"لم يتم العثور على هذا المقطع."}'),
        ('MUSIC_FILE_TYPE_INVALID', N'{"en":"The file type {0} is not supported.","hi":"फ़ाइल प्रकार {0} समर्थित नहीं है।","ar":"نوع الملف {0} غير مدعوم."}'),
        ('MUSIC_NO_FILES', N'{"en":"Choose at least one audio file.","hi":"कम से कम एक ऑडियो फ़ाइल चुनें।","ar":"اختر ملف صوت واحدًا على الأقل."}'),
        ('MUSIC_FILE_MISSING', N'{"en":"The audio file is missing on the server.","hi":"ऑडियो फ़ाइल सर्वर पर उपलब्ध नहीं है।","ar":"ملف الصوت غير موجود على الخادم."}'),
        ('MUSIC_TRACKS_UPLOADED', N'{"en":"{0} track(s) added.","hi":"{0} ट्रैक जोड़े गए।","ar":"تمت إضافة {0} مقطع."}'),
        ('MUSIC_TRACK_DELETED', N'{"en":"The track was deleted.","hi":"ट्रैक हटा दिया गया।","ar":"تم حذف المقطع."}'),
        ('YOUTUBE_QUERY_REQUIRED', N'{"en":"Enter a search text.","hi":"खोजने के लिए कुछ लिखें।","ar":"أدخل نص البحث."}'),
        ('YOUTUBE_VIDEO_ID_INVALID', N'{"en":"This is not a valid video id.","hi":"यह मान्य वीडियो आईडी नहीं है।","ar":"معرّف الفيديو غير صالح."}'),
        ('YOUTUBE_PLAYLIST_ID_INVALID', N'{"en":"This is not a valid playlist id.","hi":"यह मान्य प्लेलिस्ट आईडी नहीं है।","ar":"معرّف قائمة التشغيل غير صالح."}'),
        ('YOUTUBE_LOOKUP_FAILED', N'{"en":"YouTube could not be reached for this request.","hi":"इस अनुरोध के लिए YouTube से संपर्क नहीं हो सका।","ar":"تعذر الوصول إلى يوتيوب لهذا الطلب."}'),
        ('YOUTUBE_NO_AUDIO', N'{"en":"No audio stream is available for this video.","hi":"इस वीडियो के लिए कोई ऑडियो स्ट्रीम उपलब्ध नहीं है।","ar":"لا يتوفر مسار صوتي لهذا الفيديو."}'),
        ('TRANSLATION_LANGUAGE_INVALID', N'{"en":"This language is not supported.","hi":"यह भाषा समर्थित नहीं है।","ar":"هذه اللغة غير مدعومة."}'),
        ('TOO_MANY_REQUESTS', N'{"en":"Too many attempts. Please wait a few minutes and try again.","hi":"बहुत अधिक प्रयास। कृपया कुछ मिनट प्रतीक्षा करें और फिर प्रयास करें।","ar":"محاولات كثيرة جدًا. يرجى الانتظار بضع دقائق ثم المحاولة مرة أخرى."}'),
        ('YOUTUBE_FFMPEG_MISSING', N'{"en":"MP3 conversion is not available on this server.","hi":"इस सर्वर पर MP3 रूपांतरण उपलब्ध नहीं है।","ar":"تحويل MP3 غير متاح على هذا الخادم."}'),
        ('YOUTUBE_KEY_SAVED', N'{"en":"The YouTube API key was saved.","hi":"YouTube API कुंजी सहेज ली गई।","ar":"تم حفظ مفتاح YouTube API."}'),
        ('YOUTUBE_KEY_REJECTED', N'{"en":"YouTube did not accept this API key. Check the key and that the YouTube Data API v3 is enabled for it.","hi":"YouTube ने यह API कुंजी स्वीकार नहीं की। कुंजी जाँचें और देखें कि उसके लिए YouTube Data API v3 चालू है।","ar":"لم يقبل YouTube مفتاح API هذا. تحقق من المفتاح ومن تفعيل YouTube Data API v3 له."}'),
        ('SETTINGS_SAVED', N'{"en":"Settings saved.","hi":"सेटिंग्स सहेजी गईं।","ar":"تم حفظ الإعدادات."}'),
        ('SETTINGS_INVALID', N'{"en":"Some of the settings are not valid.","hi":"कुछ सेटिंग्स मान्य नहीं हैं।","ar":"بعض الإعدادات غير صالحة."}'),
        ('APP_NAME_SAVED', N'{"en":"App name saved.","hi":"ऐप का नाम सहेजा गया।","ar":"تم حفظ اسم التطبيق."}'),
        ('APP_NAME_INVALID', N'{"en":"Enter an English name of up to {0} characters.","hi":"अधिकतम {0} अक्षरों का अंग्रेज़ी नाम लिखें।","ar":"أدخل اسمًا باللغة الإنجليزية لا يزيد عن {0} حرفًا."}'),
        ('KHATA_BOOK_NOT_FOUND', N'{"en":"This book was not found.","hi":"यह खाता-बही नहीं मिली।","ar":"لم يتم العثور على هذا الدفتر."}'),
        ('KHATA_BOOK_NAME_INVALID', N'{"en":"Enter a book name of up to {0} characters.","hi":"अधिकतम {0} अक्षरों का बही का नाम दर्ज करें।","ar":"أدخل اسم دفتر لا يزيد عن {0} حرفًا."}'),
        ('KHATA_BOOK_NAME_TAKEN', N'{"en":"You already have a book with this name.","hi":"इस नाम की बही आपके पास पहले से है।","ar":"لديك بالفعل دفتر بهذا الاسم."}'),
        ('KHATA_BOOK_CURRENCY_LOCKED', N'{"en":"The money type of a book can''t be changed after its first entry.","hi":"पहली एंट्री के बाद बही की मुद्रा नहीं बदली जा सकती।","ar":"لا يمكن تغيير عملة الدفتر بعد أول قيد فيه."}'),
        ('KHATA_BOOK_DELETED', N'{"en":"The book has been deleted.","hi":"बही हटा दी गई है।","ar":"تم حذف الدفتر."}'),
        ('KHATA_BOOK_LIMIT', N'{"en":"You can have up to {0} books.","hi":"आप अधिकतम {0} बही रख सकते हैं।","ar":"يمكنك امتلاك {0} دفاتر كحد أقصى."}'),
        ('KHATA_CURRENCY_LIMIT', N'{"en":"You can add up to {0} money types of your own.","hi":"आप अधिकतम {0} अपनी मुद्राएँ जोड़ सकते हैं।","ar":"يمكنك إضافة {0} عملات خاصة بك كحد أقصى."}'),
        ('KHATA_CONTACT_LIMIT', N'{"en":"A book can have up to {0} contacts.","hi":"एक बही में अधिकतम {0} संपर्क हो सकते हैं।","ar":"يمكن أن يحتوي الدفتر على {0} جهة اتصال كحد أقصى."}'),
        ('KHATA_CURRENCY_NOT_FOUND', N'{"en":"This money type was not found.","hi":"यह मुद्रा नहीं मिली।","ar":"لم يتم العثور على هذه العملة."}'),
        ('KHATA_CURRENCY_INVALID', N'{"en":"Enter a code and a symbol of up to 10 characters, a name of up to 50 characters, and 0 to 3 decimals.","hi":"अधिकतम 10 अक्षरों का कोड और चिह्न, अधिकतम 50 अक्षरों का नाम और 0 से 3 दशमलव दर्ज करें।","ar":"أدخل رمزًا ورمز عرض لا يزيد كل منهما عن 10 أحرف، واسمًا لا يزيد عن 50 حرفًا، ومن 0 إلى 3 خانات عشرية."}'),
        ('KHATA_CURRENCY_CODE_TAKEN', N'{"en":"A money type with this code already exists.","hi":"इस कोड की मुद्रा पहले से मौजूद है।","ar":"توجد عملة بهذا الرمز بالفعل."}'),
        ('KHATA_CURRENCY_IN_USE', N'{"en":"This money type is used by a book, so its code and decimals can''t change and it can''t be removed.","hi":"यह मुद्रा किसी बही में उपयोग हो रही है, इसलिए इसका कोड और दशमलव नहीं बदले जा सकते और इसे हटाया नहीं जा सकता।","ar":"هذه العملة مستخدمة في دفتر، لذا لا يمكن تغيير رمزها وخاناتها العشرية ولا حذفها."}'),
        ('KHATA_CURRENCY_DELETED', N'{"en":"The money type has been removed.","hi":"मुद्रा हटा दी गई है।","ar":"تمت إزالة العملة."}'),
        ('KHATA_CONTACT_NOT_FOUND', N'{"en":"This contact was not found.","hi":"यह संपर्क नहीं मिला।","ar":"لم يتم العثور على جهة الاتصال هذه."}'),
        ('KHATA_CONTACT_INVALID', N'{"en":"Enter a name of up to {0} characters. A mobile number or email, if given, must be valid.","hi":"अधिकतम {0} अक्षरों का नाम दर्ज करें। मोबाइल नंबर या ईमेल देने पर वह मान्य होना चाहिए।","ar":"أدخل اسمًا لا يزيد عن {0} حرف. يجب أن يكون رقم الجوال أو البريد الإلكتروني صالحًا إذا أدخلته."}'),
        ('KHATA_CONTACT_DELETED', N'{"en":"The contact has been deleted.","hi":"संपर्क हटा दिया गया है।","ar":"تم حذف جهة الاتصال."}'),
        ('KHATA_CONTACT_RESTORED', N'{"en":"The contact has been restored.","hi":"संपर्क फिर से चालू कर दिया गया है।","ar":"تمت استعادة جهة الاتصال."}'),
        ('KHATA_ENTRY_NOT_FOUND', N'{"en":"This entry was not found.","hi":"यह एंट्री नहीं मिली।","ar":"لم يتم العثور على هذا القيد."}'),
        ('KHATA_ENTRY_INVALID', N'{"en":"Enter an amount above zero, a valid date and a note of up to {0} characters.","hi":"शून्य से अधिक राशि, मान्य तारीख और अधिकतम {0} अक्षरों का नोट दर्ज करें।","ar":"أدخل مبلغًا أكبر من صفر وتاريخًا صالحًا وملاحظة لا تزيد عن {0} حرف."}'),
        ('KHATA_ENTRY_NOT_YOURS', N'{"en":"You can only change entries you added.","hi":"आप केवल अपनी जोड़ी हुई एंट्री ही बदल सकते हैं।","ar":"يمكنك تعديل القيود التي أضفتها أنت فقط."}'),
        ('KHATA_ENTRY_DELETED', N'{"en":"The entry has been deleted.","hi":"एंट्री हटा दी गई है।","ar":"تم حذف القيد."}'),
        ('KHATA_CHANGED_ELSEWHERE', N'{"en":"This was changed by someone else. Reload and try again.","hi":"इसे किसी और ने बदल दिया है। फिर से लोड करें और दोबारा प्रयास करें।","ar":"قام شخص آخر بتغيير هذا. أعد التحميل وحاول مرة أخرى."}'),
        ('KHATA_REQUEST_IN_PROGRESS', N'{"en":"This request is already being processed.","hi":"यह अनुरोध पहले से प्रोसेस हो रहा है।","ar":"هذا الطلب قيد المعالجة بالفعل."}'),
        ('KHATA_REQUEST_KEY_REUSED', N'{"en":"This request key was already used for a different request.","hi":"यह अनुरोध कुंजी किसी दूसरे अनुरोध के लिए पहले ही उपयोग हो चुकी है।","ar":"تم استخدام مفتاح الطلب هذا بالفعل لطلب مختلف."}'),
        ('KHATA_QUERY_INVALID', N'{"en":"Some of the filters are not valid.","hi":"कुछ फ़िल्टर मान्य नहीं हैं।","ar":"بعض عوامل التصفية غير صالحة."}'),
        ('KHATA_PHOTO_INVALID', N'{"en":"Add JPG, PNG, WebP or GIF photos of up to {0} MB each.","hi":"हर फ़ोटो {0} MB तक की JPG, PNG, WebP या GIF होनी चाहिए।","ar":"أضف صور JPG أو PNG أو WebP أو GIF لا يزيد حجم كل منها عن {0} ميغابايت."}'),
        ('KHATA_PHOTO_LIMIT', N'{"en":"An entry can have up to {0} photos.","hi":"एक एंट्री में अधिकतम {0} फ़ोटो हो सकती हैं।","ar":"يمكن أن يحتوي القيد على {0} صور كحد أقصى."}'),
        ('KHATA_ATTACHMENT_NOT_FOUND', N'{"en":"This photo was not found.","hi":"यह फ़ोटो नहीं मिली।","ar":"لم يتم العثور على هذه الصورة."}'),
        ('KHATA_ATTACHMENT_DELETED', N'{"en":"The photo has been removed.","hi":"फ़ोटो हटा दी गई है।","ar":"تمت إزالة الصورة."}'),
        ('KHATA_CONTACT_PHOTO_SAVED', N'{"en":"The picture was saved.","hi":"तस्वीर सहेज ली गई।","ar":"تم حفظ الصورة."}'),
        ('KHATA_CONTACT_PHOTO_DELETED', N'{"en":"The picture was removed.","hi":"तस्वीर हटा दी गई।","ar":"تمت إزالة الصورة."}'),
        ('KHATA_CONTACT_PHOTO_NOT_FOUND', N'{"en":"This party has no picture.","hi":"इस पार्टी की कोई तस्वीर नहीं है।","ar":"لا توجد صورة لهذا الطرف."}'),
        ('KHATA_CONTACT_PHOTO_INVALID', N'{"en":"Choose a JPG, PNG or WebP picture of up to {0} KB.","hi":"{0} KB तक की JPG, PNG या WebP तस्वीर चुनें।","ar":"اختر صورة JPG أو PNG أو WebP بحجم {0} كيلوبايت كحد أقصى."}'),
        ('AUTH_OTP_SENT', N'{"en":"We sent you a login code. It works for {0} minutes.","hi":"हमने आपको लॉग इन कोड भेजा है। यह {0} मिनट तक काम करेगा।","ar":"أرسلنا إليك رمز تسجيل الدخول. يعمل الرمز لمدة {0} دقيقة."}'),
        ('OTP_TOO_MANY_REQUESTS', N'{"en":"Too many code requests. Try again in {0} seconds.","hi":"बहुत सारे कोड अनुरोध। {0} सेकंड बाद फिर से प्रयास करें।","ar":"طلبات رموز كثيرة جدًا. حاول مرة أخرى بعد {0} ثانية."}'),
        ('AUTH_OTP_INVALID', N'{"en":"The code is wrong or has expired. Ask for a new code.","hi":"कोड गलत है या उसकी समय-सीमा खत्म हो गई है। नया कोड माँगें।","ar":"الرمز غير صحيح أو انتهت صلاحيته. اطلب رمزًا جديدًا."}'),
        ('AUTH_OTP_SMS_TEXT', N'{"en":"{0} is your login code. It works for {1} minutes. Do not share it with anyone.","hi":"{0} आपका लॉग इन कोड है। यह {1} मिनट तक काम करेगा। इसे किसी के साथ साझा न करें।","ar":"{0} هو رمز تسجيل الدخول الخاص بك. يعمل لمدة {1} دقيقة. لا تشاركه مع أي شخص."}'),
        ('AUTH_OTP_EMAIL_SUBJECT', N'{"en":"Your login code: {0}","hi":"आपका लॉग इन कोड: {0}","ar":"رمز تسجيل الدخول الخاص بك: {0}"}'),
        ('AUTH_OTP_EMAIL_LEAD', N'{"en":"Your login code is","hi":"आपका लॉग इन कोड है","ar":"رمز تسجيل الدخول الخاص بك هو"}'),
        ('AUTH_OTP_EMAIL_BODY', N'{"en":"It works for {0} minutes. If you did not ask for this code, you can ignore this e-mail.","hi":"यह {0} मिनट तक काम करेगा। अगर आपने यह कोड नहीं माँगा था, तो इस ई-मेल को अनदेखा करें।","ar":"يعمل لمدة {0} دقيقة. إذا لم تطلب هذا الرمز، يمكنك تجاهل هذا البريد الإلكتروني."}'),
        ('AUTH_DELETED_EMAIL_SUBJECT', N'{"en":"Your Thakurg account was deleted","hi":"आपका Thakurg खाता हटा दिया गया","ar":"تم حذف حسابك في Thakurg"}'),
        ('AUTH_DELETED_EMAIL_HELLO', N'{"en":"Hello {0},","hi":"नमस्ते {0},","ar":"مرحبًا {0}،"}'),
        ('AUTH_DELETED_EMAIL_BODY', N'{"en":"Your account {0} was deleted on {1}. You were logged out on every device, and this e-mail address can no longer be used to log in.","hi":"आपका खाता {0} {1} को हटा दिया गया। आपको हर डिवाइस से लॉग आउट कर दिया गया है, और इस ई-मेल पते से अब लॉग इन नहीं किया जा सकता।","ar":"تم حذف حسابك {0} بتاريخ {1}. تم تسجيل خروجك من جميع الأجهزة، ولم يعد بالإمكان استخدام هذا البريد الإلكتروني لتسجيل الدخول."}'),
        ('AUTH_DELETED_EMAIL_WARNING', N'{"en":"If you did not delete your account, contact the site administrator right away.","hi":"अगर आपने अपना खाता नहीं हटाया, तो तुरंत साइट व्यवस्थापक से संपर्क करें।","ar":"إذا لم تحذف حسابك، فتواصل مع مسؤول الموقع فورًا."}'),
        ('AUTH_QUICK_LOGIN_SAVED', N'{"en":"This user is now shown on the login page.","hi":"यह उपयोगकर्ता अब लॉगिन पेज पर दिखता है।","ar":"يظهر هذا المستخدم الآن في صفحة الدخول."}'),
        ('AUTH_QUICK_LOGIN_REMOVED', N'{"en":"This user is no longer shown on the login page.","hi":"यह उपयोगकर्ता अब लॉगिन पेज पर नहीं दिखता।","ar":"لم يعد هذا المستخدم يظهر في صفحة الدخول."}'),
        ('AUTH_QUICK_LOGIN_UNAVAILABLE', N'{"en":"This quick login is not available.","hi":"यह क्विक लॉगिन उपलब्ध नहीं है।","ar":"تسجيل الدخول السريع هذا غير متاح."}'),
        ('EMAIL_BRAND', N'{"en":"Thakurg","hi":"Thakurg","ar":"Thakurg"}'),
        ('EMAIL_FOOTER', N'{"en":"This is an automatic message from {0}. Please do not reply.","hi":"यह {0} का स्वचालित संदेश है। कृपया इसका उत्तर न दें।","ar":"هذه رسالة تلقائية من {0}. يرجى عدم الرد عليها."}'),
        ('AUTH_OTP_APP_INVALID', N'{"en":"Login with a code is not available for this app.","hi":"इस ऐप के लिए कोड से लॉग इन उपलब्ध नहीं है।","ar":"تسجيل الدخول برمز غير متاح لهذا التطبيق."}'),
        ('AUTH_OTP_DESTINATION_INVALID', N'{"en":"Enter a valid e-mail address or mobile number.","hi":"मान्य ई-मेल पता या मोबाइल नंबर दर्ज करें।","ar":"أدخل بريدًا إلكترونيًا أو رقم جوال صالحًا."}'),
        ('AUTH_OTP_ACCOUNT_NOT_FOUND', N'{"en":"No account is registered with this e-mail address or mobile number.","hi":"इस ई-मेल पते या मोबाइल नंबर से कोई खाता पंजीकृत नहीं है।","ar":"لا يوجد حساب مسجل بهذا البريد الإلكتروني أو رقم الجوال."}'),
        ('EMAIL_NOT_CONFIGURED', N'{"en":"Sending e-mail is not set up yet. Please try again later.","hi":"ई-मेल भेजना अभी सेट नहीं है। कृपया बाद में प्रयास करें।","ar":"إرسال البريد الإلكتروني غير مُعدّ بعد. يرجى المحاولة لاحقًا."}'),
        ('EMAIL_SEND_FAILED', N'{"en":"The e-mail could not be sent. Please try again later.","hi":"ई-मेल नहीं भेजा जा सका। कृपया बाद में प्रयास करें।","ar":"تعذّر إرسال البريد الإلكتروني. يرجى المحاولة لاحقًا."}'),
        ('MAIL_SAVED', N'{"en":"The mail settings were saved.","hi":"मेल सेटिंग्स सहेज ली गईं।","ar":"تم حفظ إعدادات البريد."}'),
        ('MAIL_INVALID', N'{"en":"Check the mail settings: a switched-on server needs a host, a port from 1 to 65535 and a valid From address.","hi":"मेल सेटिंग्स जांचें: चालू सर्वर के लिए होस्ट, 1 से 65535 तक का पोर्ट और सही From पता चाहिए।","ar":"تحقق من إعدادات البريد: الخادم المفعّل يحتاج إلى مضيف ومنفذ من 1 إلى 65535 وعنوان مرسل صحيح."}'),
        ('MAIL_TEST_OFF', N'{"en":"Switch this mail server on and save it before sending a test e-mail.","hi":"टेस्ट ई-मेल भेजने से पहले इस मेल सर्वर को चालू करके सहेजें।","ar":"فعّل خادم البريد هذا واحفظه قبل إرسال رسالة اختبار."}'),
        ('MAIL_TEST_BODY', N'{"en":"This is a test e-mail from Thakurg. If you can read it, these mail settings work.","hi":"यह Thakurg का टेस्ट ई-मेल है। अगर आप इसे पढ़ पा रहे हैं, तो ये मेल सेटिंग्स काम कर रही हैं।","ar":"هذه رسالة اختبار من Thakurg. إذا كنت تقرؤها، فإعدادات البريد هذه تعمل."}'),
        ('MAIL_TEST_SENT', N'{"en":"A test e-mail was sent to {0}.","hi":"टेस्ट ई-मेल {0} पर भेजा गया।","ar":"تم إرسال رسالة اختبار إلى {0}."}'),
        ('MAIL_TEST_SUBJECT', N'{"en":"Thakurg test e-mail","hi":"Thakurg टेस्ट ई-मेल","ar":"رسالة اختبار من Thakurg"}'),
        ('SMS_NOT_CONFIGURED', N'{"en":"Text messages are not set up yet. Use e-mail instead.","hi":"एसएमएस अभी सेट नहीं है। इसके बजाय ई-मेल का उपयोग करें।","ar":"الرسائل النصية غير مُعدّة بعد. استخدم البريد الإلكتروني بدلًا منها."}'),
        ('WHATSAPP_NOT_CONFIGURED', N'{"en":"WhatsApp messages are not set up yet. Use e-mail instead.","hi":"व्हाट्सऐप संदेश अभी सेट नहीं हैं। इसके बजाय ई-मेल का उपयोग करें।","ar":"رسائل واتساب غير مُعدّة بعد. استخدم البريد الإلكتروني بدلًا منها."}'),
        ('PROFILE_DETAILS_SAVED', N'{"en":"Your details were saved.","hi":"आपका विवरण सहेज लिया गया।","ar":"تم حفظ بياناتك."}'),
        ('PROFILE_DETAILS_INVALID', N'{"en":"Check your details: a field is too long, or an e-mail address or phone number is not valid.","hi":"अपना विवरण जाँचें: कोई फ़ील्ड बहुत लंबा है, या कोई ई-मेल पता या फ़ोन नंबर मान्य नहीं है।","ar":"تحقق من بياناتك: أحد الحقول طويل جدًا، أو أن بريدًا إلكترونيًا أو رقم هاتف غير صالح."}'),
        ('PROFILE_MOBILE_TAKEN', N'{"en":"This mobile number is already used by another account.","hi":"यह मोबाइल नंबर पहले से किसी दूसरे खाते में उपयोग हो रहा है।","ar":"رقم الجوال هذا مستخدم بالفعل في حساب آخر."}'),
        ('EXPORT_FORMAT_INVALID', N'{"en":"Choose PDF, CSV or Excel (xlsx).","hi":"PDF, CSV या Excel (xlsx) चुनें।","ar":"اختر PDF أو CSV أو Excel (xlsx)."}'),
        ('KHATA_SETTINGS_SAVED', N'{"en":"Your settings were saved.","hi":"आपकी सेटिंग्स सहेज ली गईं।","ar":"تم حفظ إعداداتك."}'),
        ('KHATA_NOTIFY_SAVED', N'{"en":"Message settings for this party were saved.","hi":"इस पार्टी की संदेश सेटिंग्स सहेज ली गईं।","ar":"تم حفظ إعدادات الرسائل لهذا الطرف."}'),
        ('KHATA_NOTIFY_EMAIL_MISSING', N'{"en":"Add an e-mail address for this party before turning on e-mail messages.","hi":"ई-मेल संदेश चालू करने से पहले इस पार्टी का ई-मेल पता जोड़ें।","ar":"أضف بريدًا إلكترونيًا لهذا الطرف قبل تفعيل رسائل البريد الإلكتروني."}'),
        ('KHATA_NOTIFY_MOBILE_MISSING', N'{"en":"Add a mobile number for this party before turning on SMS.","hi":"एसएमएस चालू करने से पहले इस पार्टी का मोबाइल नंबर जोड़ें।","ar":"أضف رقم جوال لهذا الطرف قبل تفعيل الرسائل النصية."}'),
        ('KHATA_NOTIFY_WHATSAPP_MISSING', N'{"en":"Add a mobile number for this party before turning on WhatsApp messages.","hi":"व्हाट्सऐप संदेश चालू करने से पहले इस पार्टी का मोबाइल नंबर जोड़ें।","ar":"أضف رقم جوال لهذا الطرف قبل تفعيل رسائل واتساب."}'),
        ('KHATA_PIN_INVALID', N'{"en":"Enter a PIN of exactly {0} digits.","hi":"ठीक {0} अंकों का PIN दर्ज करें।","ar":"أدخل رمز PIN من {0} أرقام بالضبط."}'),
        ('KHATA_PIN_WEAK', N'{"en":"This PIN is too easy to guess. Avoid repeated digits (1111) and runs (1234).","hi":"यह PIN आसानी से अनुमान लगाया जा सकता है। एक जैसे अंक (1111) और क्रम (1234) से बचें।","ar":"رمز PIN هذا سهل التخمين. تجنّب تكرار الرقم (1111) والتسلسل (1234)."}'),
        ('KHATA_PIN_WRONG', N'{"en":"Wrong PIN. {0} tries left before the app is locked for a while.","hi":"गलत PIN। ऐप कुछ देर के लिए लॉक होने से पहले {0} कोशिशें बाकी हैं।","ar":"رمز PIN خاطئ. تبقّت {0} محاولات قبل قفل التطبيق لفترة."}'),
        ('KHATA_PIN_LOCKED', N'{"en":"Too many wrong PINs. Try again in {0} minutes, or log in again.","hi":"बहुत सारे गलत PIN। {0} मिनट बाद फिर कोशिश करें, या फिर से लॉग इन करें।","ar":"محاولات PIN خاطئة كثيرة. حاول مرة أخرى بعد {0} دقيقة، أو سجّل الدخول من جديد."}'),
        ('KHATA_PIN_CLEARED', N'{"en":"Too many wrong PINs. You have been logged out everywhere. Log in again and choose a new PIN.","hi":"बहुत सारे गलत PIN। आपको हर जगह से लॉग आउट कर दिया गया है। फिर से लॉग इन करें और नया PIN चुनें।","ar":"محاولات PIN خاطئة كثيرة. تم تسجيل خروجك من كل الأجهزة. سجّل الدخول من جديد واختر رمز PIN جديدًا."}'),
        ('KHATA_PIN_REQUIRED', N'{"en":"The app is locked. Enter your PIN to continue.","hi":"ऐप लॉक है। जारी रखने के लिए अपना PIN दर्ज करें।","ar":"التطبيق مقفل. أدخل رمز PIN للمتابعة."}'),
        ('KHATA_PIN_SAVED', N'{"en":"Your app lock PIN was saved.","hi":"आपका ऐप लॉक PIN सहेज लिया गया।","ar":"تم حفظ رمز PIN لقفل التطبيق."}'),
        ('KHATA_PIN_NOT_SET', N'{"en":"You have not set an app lock PIN yet.","hi":"आपने अभी तक ऐप लॉक PIN सेट नहीं किया है।","ar":"لم تقم بتعيين رمز PIN لقفل التطبيق بعد."}'),
        ('KHATA_NOTIFY_SUBJECT', N'{"en":"{0} updated your account","hi":"{0} ने आपका खाता अपडेट किया","ar":"قام {0} بتحديث حسابك"}'),
        ('KHATA_NOTIFY_ADDED', N'{"en":"{0} added an entry: {1} on {2}.","hi":"{0} ने एक एंट्री जोड़ी: {2} को {1}।","ar":"أضاف {0} قيدًا: {1} بتاريخ {2}."}'),
        ('KHATA_NOTIFY_EDITED', N'{"en":"{0} changed an entry: {1} on {2}.","hi":"{0} ने एक एंट्री बदली: {2} को {1}।","ar":"عدّل {0} قيدًا: {1} بتاريخ {2}."}'),
        ('KHATA_NOTIFY_DELETED', N'{"en":"{0} deleted an entry: {1} on {2}.","hi":"{0} ने एक एंट्री हटाई: {2} को {1}।","ar":"حذف {0} قيدًا: {1} بتاريخ {2}."}'),
