        ('WHATSAPP_SAVED', N'{"en":"WhatsApp settings saved.","hi":"व्हाट्सऐप सेटिंग्स सहेजी गईं।","ar":"تم حفظ إعدادات واتساب."}'),
        ('WHATSAPP_INVALID', N'{"en":"Check the WhatsApp settings: phone number id and account id are digits, the version looks like v21.0, the template name uses lower-case letters, digits and _, and an access token is needed to switch it on.","hi":"व्हाट्सऐप सेटिंग्स जांचें: फ़ोन नंबर आईडी और अकाउंट आईडी अंकों में हों, वर्ज़न v21.0 जैसा हो, टेम्पलेट नाम में छोटे अक्षर, अंक और _ हों, और चालू करने के लिए एक्सेस टोकन ज़रूरी है।","ar":"تحقق من إعدادات واتساب: معرّف رقم الهاتف ومعرّف الحساب أرقام، والإصدار مثل v21.0، واسم القالب أحرف صغيرة وأرقام و_، ويلزم رمز وصول لتفعيله."}'),
        ('WHATSAPP_TEST_SENT', N'{"en":"Test message sent to {0}.","hi":"{0} पर टेस्ट संदेश भेजा गया।","ar":"تم إرسال رسالة اختبار إلى {0}."}'),
        ('WHATSAPP_TEST_TEXT', N'{"en":"This is a test message from thakurg.com. WhatsApp messages are working.","hi":"यह thakurg.com का टेस्ट संदेश है। व्हाट्सऐप संदेश काम कर रहे हैं।","ar":"هذه رسالة اختبار من thakurg.com. رسائل واتساب تعمل."}'),
        ('WHATSAPP_SEND_FAILED', N'{"en":"WhatsApp did not accept the message. Check the account, token and template in Settings.","hi":"व्हाट्सऐप ने संदेश स्वीकार नहीं किया। सेटिंग्स में अकाउंट, टोकन और टेम्पलेट जांचें।","ar":"لم يقبل واتساب الرسالة. تحقق من الحساب والرمز والقالب في الإعدادات."}'),
        ('WHATSAPP_NUMBER_INVALID', N'{"en":"Enter a valid mobile number, for example +91 98765 43210.","hi":"सही मोबाइल नंबर लिखें, जैसे +91 98765 43210।","ar":"أدخل رقم جوال صالحًا، مثل +91 98765 43210."}'),
        ('TASKS_SAVED', N'{"en":"Task saved.","hi":"कार्य सहेजा गया।","ar":"تم حفظ المهمة."}'),
        ('TASKS_ADDED', N'{"en":"Task added.","hi":"कार्य जोड़ा गया।","ar":"تمت إضافة المهمة."}'),
        ('TASKS_INVALID', N'{"en":"Some details are not valid. Please check and try again.","hi":"कुछ विवरण मान्य नहीं हैं। कृपया जांचें और फिर से प्रयास करें।","ar":"بعض التفاصيل غير صالحة. يرجى التحقق والمحاولة مرة أخرى."}'),
        ('TASKS_DELETED', N'{"en":"Task deleted.","hi":"कार्य हटाया गया।","ar":"تم حذف المهمة."}'),
        ('TASKS_NOT_FOUND', N'{"en":"This task was not found.","hi":"यह कार्य नहीं मिला।","ar":"لم يتم العثور على هذه المهمة."}'),
        ('TASKS_RESTORED', N'{"en":"Task restored.","hi":"कार्य वापस लाया गया।","ar":"تمت استعادة المهمة."}'),
