        ('TASKS_TITLE_REQUIRED', N'{"en":"Please enter a task title.","hi":"कृपया कार्य का शीर्षक लिखें।","ar":"يرجى إدخال عنوان المهمة."}'),
        ('TASKS_CHECKLIST_LIMIT', N'{"en":"A task can have up to {0} checklist items.","hi":"एक कार्य में अधिकतम {0} चेकलिस्ट आइटम हो सकते हैं।","ar":"يمكن أن تحتوي المهمة على {0} عنصرًا كحد أقصى في قائمة التحقق."}'),
        ('TASKS_CATEGORY_SAVED', N'{"en":"Category saved.","hi":"श्रेणी सहेजी गई।","ar":"تم حفظ الفئة."}'),
        ('TASKS_CATEGORY_DELETED', N'{"en":"Category deleted. Its tasks now have no category.","hi":"श्रेणी हटाई गई। इसके कार्य अब बिना श्रेणी के हैं।","ar":"تم حذف الفئة. مهامها الآن بدون فئة."}'),
        ('TASKS_CATEGORY_NOT_FOUND', N'{"en":"This category was not found.","hi":"यह श्रेणी नहीं मिली।","ar":"لم يتم العثور على هذه الفئة."}'),
        ('TASKS_CATEGORY_SYSTEM', N'{"en":"Marketing is built in: it cannot be renamed or deleted.","hi":"मार्केटिंग अंतर्निहित है: इसका नाम बदला या हटाया नहीं जा सकता।","ar":"التسويق فئة مدمجة: لا يمكن إعادة تسميتها أو حذفها."}'),
        ('TASKS_CATEGORY_LIMIT', N'{"en":"You can have up to {0} categories.","hi":"आप अधिकतम {0} श्रेणियां रख सकते हैं।","ar":"يمكنك إنشاء {0} فئة كحد أقصى."}'),
        ('TASKS_PHOTO_ADDED', N'{"en":"Pictures added.","hi":"तस्वीरें जोड़ी गईं।","ar":"تمت إضافة الصور."}'),
        ('TASKS_PHOTO_REMOVED', N'{"en":"Picture removed.","hi":"तस्वीर हटाई गई।","ar":"تمت إزالة الصورة."}'),
        ('TASKS_PHOTO_NOT_FOUND', N'{"en":"This picture was not found.","hi":"यह तस्वीर नहीं मिली।","ar":"لم يتم العثور على هذه الصورة."}'),
        ('TASKS_PHOTO_LIMIT', N'{"en":"A task can have up to {0} pictures.","hi":"एक कार्य में अधिकतम {0} तस्वीरें हो सकती हैं।","ar":"يمكن أن تحتوي المهمة على {0} صور كحد أقصى."}'),
        ('TASKS_PHOTO_INVALID', N'{"en":"Only JPG, PNG, WebP or GIF pictures up to {0} MB can be attached.","hi":"केवल {0} MB तक की JPG, PNG, WebP या GIF तस्वीरें जोड़ी जा सकती हैं।","ar":"يمكن إرفاق صور JPG أو PNG أو WebP أو GIF فقط بحجم يصل إلى {0} ميغابايت."}'),
        ('TASKS_SETTINGS_SAVED', N'{"en":"Settings saved.","hi":"सेटिंग्स सहेजी गईं।","ar":"تم حفظ الإعدادات."}'),
